  <path d="M21 24h54M21 36h54M21 48h54M21 60h34" fill="none" stroke="#f2e8d6" stroke-width="3"/>
  <path d="M35 74h40" fill="none" stroke="#ffae91" stroke-width="3"/>
</svg>
